use std::{fs,time::Instant,io::Cursor};
fn main()->Result<(),Box<dyn std::error::Error>>{
 let mut rows=Vec::new();
 for i in 0..8 {
  let input=fs::read(format!("/home/gurp/softs/tack/benchmark-data/mission0/sources/source-{i:04}.jpg"))?;
  for edge in [64,96,128,512,2048] {
   for scaled in [false,true] {
    let start=Instant::now();
    let image=if scaled {
     let mut d=jpeg_decoder::Decoder::new(Cursor::new(&input));d.set_max_decoding_buffer_size(192*1024*1024);
     d.scale(edge as u16,(edge*3/4) as u16)?;
     let pixels=d.decode()?;let info=d.info().ok_or("no JPEG metadata")?;
     image::DynamicImage::ImageRgb8(image::RgbImage::from_raw(info.width.into(),info.height.into(),pixels).ok_or("bad pixels")?)
    }else{image::load_from_memory_with_format(&input,image::ImageFormat::Jpeg)?};
    let decode=start.elapsed().as_secs_f64()*1000.; let bytes=image.as_bytes().len();
    let start=Instant::now();let thumb=image.thumbnail(edge,edge);let resize=start.elapsed().as_secs_f64()*1000.;
    rows.push(serde_json::json!({"source":i,"edge":edge,"scaled":scaled,"decode_ms":decode,"resize_ms":resize,"decoded_bytes":bytes,"output_bytes":thumb.into_rgba8().as_raw().len()}));
   }
  }
 }
 println!("{}",serde_json::to_string_pretty(&rows)?);Ok(())
}
